class MT19937Predictor:
    def __init__(self):
        self.state = [0] * 624
        self.index = 0
        self._predictable = False

    def setrandbits(self, value, bits):
        assert bits == 32, "Only 32-bit values are supported"
        self.state[self.index] = self._untwist(value)
        self.index += 1
        if self.index == 624:
            self._predictable = True
            self.index = 0

    def random(self):
        if not self._predictable:
            raise Exception("State is not fully initialized, can't predict yet.")

        if self.index == 0:
            self._twist()

        y = self.state[self.index]
        y ^= (y >> 11)
        y ^= (y << 7) & 0x9D2C5680
        y ^= (y << 15) & 0xEFC60000
        y ^= (y >> 18)

        self.index += 1
        self.index %= 624
        return y

    def _untwist(self, value):
        y = value
        y ^= (y >> 18)
        y ^= (y << 15) & 0xEFC60000
        for _ in range(7):
            y ^= (y << 7) & 0x9D2C5680
        for _ in range(3):
            y ^= (y >> 11)
        return y & 0xFFFFFFFF

    def _twist(self):
        for i in range(624):
            y = (self.state[i] & 0x80000000) + (self.state[(i + 1) % 624] & 0x7FFFFFFF)
            self.state[i] = self.state[(i + 397) % 624] ^ (y >> 1)
            if y % 2 != 0:
                self.state[i] ^= 0x9908B0DF

